// Writes the docs' Changelog page from the repository's CHANGELOG.md, so the
// two never drift: src/content/docs/docs/changelog.md is generated by every
// build and dev run (see package.json) and is not committed (see .gitignore).
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dir, "..");
const source = readFileSync(join(root, "..", "CHANGELOG.md"), "utf8");

// Starlight takes the title from the frontmatter, so drop the file's own "# Changelog".
const body = source.replace(/^# Changelog\s*\n/, "");

const page = `---
title: Changelog
description: Every change to Ursa, the ursa CLI and the Python library, newest first.
editUrl: https://github.com/cldixon/ursa/edit/main/CHANGELOG.md
---

<!-- Generated from CHANGELOG.md by site/scripts/changelog.ts. Edit CHANGELOG.md, not this page. -->

${body}`;

writeFileSync(join(root, "src/content/docs/docs/changelog.md"), page);
console.log("wrote src/content/docs/docs/changelog.md from CHANGELOG.md");
